SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.dischtime - a.admittime AS length_of_stay, percent_rank() OVER (ORDER BY (a.dischtime - a.admittime)) AS percentile_rank, (a.dischtime - a.admittime) AS median_length_of_stay, (percentile_cont(0.75) within GROUP (ORDER BY (a.dischtime - a.admittime)) - percentile_cont(0.25) within GROUP (ORDER BY (a.dischtime - a.admittime))) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_age = 48 AND p.anchor_year = 2017 AND p.anchor_year_group = '43-53' AND a.admission_type = 'ED' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, length_of_stay;